INSERT INTO `resource` VALUES (5,'‘Biga baloma / Biga tommwaya’ and ‘Wosi milamala’ – ‘Speech of the spirits of the dead / Old peoples’ speech’ and ‘songs of the harvest festival’','Chapter 4','http://dx.doi.org/10.1515/9783110227994.26',1,1000,0,NULL,NULL,1,NULL,NULL),(6,NULL,'Sound recording Tauwema_1983_T1_sideA','http://hdl.handle.net/1839/00-0000-0000-0005-6798-1',1,1000,1,NULL,NULL,1,NULL,NULL),(7,NULL,'Sound recording Tauwema_1983_T1_sideB','http://hdl.handle.net/1839/00-0000-0000-0005-6797-3',1,1000,2,NULL,NULL,1,NULL,NULL),(8,'‘Biga megwa’ and ‘megwa’ – ‘Magic speech’ and ‘magical formulae’','Chapter 5','http://dx.doi.org/10.1515/9783110227994.40',1,1000,3,NULL,NULL,1,NULL,NULL),(9,NULL,'Sound recording Magie_1989_sideA','http://hdl.handle.net/1839/00-0000-0000-0004-9221-F',1,1000,4,NULL,NULL,1,NULL,NULL),(10,NULL,'Sound recording Magie_1989_sideB','http://hdl.handle.net/1839/00-0000-0000-0004-9222-1',1,1000,5,NULL,NULL,1,NULL,NULL),(11,'This film presents (1) the documentation of the \'kedidagi\' - the fishing with a torch on the reef, (2) Gerubara telling a version of the Dokonikani story in my house in the evening (3) Mokeilobu telling a story about a reef formation and reciting the \'kevalikuliku\' magic on the reef formation close to Giwa','Video Recording Stories_Magic_1994','http://hdl.handle.net/1839/00-0000-0000-0004-9227-3',1,1000,6,NULL,NULL,1,NULL,NULL),(12,'‘Biga tapwaroro’ and ‘tapwaroro’ as well as ‘wosi tapwaroro’ – ‘Language of the church’ and ‘Christian texts’ as well as ‘church songs’','Chapter 6','http://dx.doi.org/10.1515/9783110227994.60',1,1000,7,NULL,NULL,1,NULL,NULL),(13,'Some impressions from visiting Kitava Island as a guest of  Jan Barter on board of  the Melanesian Discoverer and documentation of songs and dances staged for the tourists in Kaibola and Nuwebila','Video recording Kitava_Kaibola93','http://hdl.handle.net/1839/00-0000-0000-0005-6928-C',1,1000,8,NULL,NULL,1,NULL,NULL),(14,'Gerubara prays the \"Our Father\" prayer','S